import { randomBytes } from 'node:crypto';
import { mkdir, readFile, rename, writeFile } from 'node:fs/promises';
import { dirname } from 'node:path';

export const LIMITS = { title: 200, author: 200, notes: 5000 };

export class ValidationError extends Error {}

// Books live in memory and every change is written to a JSON file.
// Writes go to a temp file first and are renamed into place, so a crash
// mid-write never leaves a half-written books.json behind.
export async function openStore(filePath) {
  let books = [];
  try {
    books = JSON.parse(await readFile(filePath, 'utf8'));
  } catch (err) {
    // A missing file just means no books yet. Anything else (e.g. a corrupt
    // file) should stop startup rather than be silently overwritten.
    if (err.code !== 'ENOENT') throw err;
  }

  let pending = Promise.resolve();
  function save() {
    const snapshot = JSON.stringify(books, null, 2);
    pending = pending.then(async () => {
      await mkdir(dirname(filePath), { recursive: true });
      const tmp = `${filePath}.tmp`;
      await writeFile(tmp, snapshot);
      await rename(tmp, filePath);
    });
    return pending;
  }

  return {
    list() {
      return books.slice();
    },

    get(id) {
      return books.find((b) => b.id === id);
    },

    async add(input) {
      const book = {
        id: randomBytes(6).toString('hex'),
        title: clean(input.title, 'title', true),
        author: clean(input.author, 'author', true),
        notes: clean(input.notes, 'notes', false),
        addedAt: new Date().toISOString(),
        finishedAt: null,
      };
      books.push(book);
      await save();
      return book;
    },

    async finish(id) {
      const book = books.find((b) => b.id === id);
      if (!book) return undefined;
      if (!book.finishedAt) {
        book.finishedAt = new Date().toISOString();
        await save();
      }
      return book;
    },
  };
}

function clean(value, field, required) {
  const text = typeof value === 'string' ? value.trim() : '';
  if (required && !text) throw new ValidationError(`Please enter a ${field}.`);
  if (text.length > LIMITS[field]) {
    throw new ValidationError(`The ${field} can be at most ${LIMITS[field]} characters.`);
  }
  return text;
}

