import { LIMITS } from './store.js';

const escapes = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' };
export function esc(value) {
  return String(value ?? '').replace(/[&<>"']/g, (c) => escapes[c]);
}

function formatDate(iso) {
  return new Date(iso).toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' });
}

function layout(title, body) {
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${esc(title)}</title>
<style>
  body { font-family: system-ui, sans-serif; max-width: 40rem; margin: 2rem auto; padding: 0 1rem; line-height: 1.5; color: #222; }
  a { color: #2457a6; }
  h1 a { color: inherit; text-decoration: none; }
  ul { padding-left: 0; list-style: none; }
  li { display: flex; justify-content: space-between; align-items: center; gap: 1rem; padding: .5rem 0; border-bottom: 1px solid #eee; }
  .muted { color: #777; }
  .empty { color: #777; font-style: italic; }
  .error { background: #fdecea; color: #8a1c1c; padding: .5rem .75rem; border-radius: 4px; }
  form.add label { display: block; margin-top: .75rem; }
  form.add input, form.add textarea { width: 100%; box-sizing: border-box; padding: .4rem; font: inherit; }
  button { font: inherit; padding: .3rem .8rem; cursor: pointer; }
  .notes { white-space: pre-wrap; background: #f7f7f7; padding: .75rem; border-radius: 4px; }
  .share { display: flex; gap: .5rem; }
  .share input { flex: 1; padding: .3rem; font: inherit; }
</style>
</head>
<body>
<h1><a href="/">My books</a></h1>
${body}
</body>
</html>`;
}

function bookItem(book) {
  const finishButton = book.finishedAt
    ? `<span class="muted">Finished ${esc(formatDate(book.finishedAt))}</span>`
    : `<form method="post" action="/books/${esc(book.id)}/finish"><button>Mark finished</button></form>`;
  return `<li>
    <span><a href="/books/${esc(book.id)}">${esc(book.title)}</a> <span class="muted">by ${esc(book.author)}</span></span>
    ${finishButton}
  </li>`;
}

function bookList(books, emptyText) {
  if (books.length === 0) return `<p class="empty">${esc(emptyText)}</p>`;
  return `<ul>${books.map(bookItem).join('')}</ul>`;
}

export function homePage(books, { error, values = {} } = {}) {
  const reading = books.filter((b) => !b.finishedAt);
  const finished = books
    .filter((b) => b.finishedAt)
    .sort((a, b) => b.finishedAt.localeCompare(a.finishedAt));

  return layout('My books', `
<h2>Currently reading</h2>
${bookList(reading, 'Nothing on the go right now.')}

<h2>Finished</h2>
${bookList(finished, 'No finished books yet.')}

<h2 id="add">Add a book</h2>
${error ? `<p class="error">${esc(error)}</p>` : ''}
<form class="add" method="post" action="/books">
  <label>Title <input name="title" required maxlength="${LIMITS.title}" value="${esc(values.title)}"></label>
  <label>Author <input name="author" required maxlength="${LIMITS.author}" value="${esc(values.author)}"></label>
  <label>Notes <textarea name="notes" rows="4" maxlength="${LIMITS.notes}">${esc(values.notes)}</textarea></label>
  <p><button>Add book</button></p>
</form>`);
}

export function bookPage(book, shareUrl) {
  const status = book.finishedAt
    ? `Finished ${esc(formatDate(book.finishedAt))}`
    : `Reading since ${esc(formatDate(book.addedAt))}`;
  const finishForm = book.finishedAt
    ? ''
    : `<form method="post" action="/books/${esc(book.id)}/finish"><button>Mark finished</button></form>`;

  return layout(`${book.title} by ${book.author}`, `
<h2>${esc(book.title)}</h2>
<p>by ${esc(book.author)}</p>
<p class="muted">${status}</p>
${finishForm}

<h3>Notes</h3>
${book.notes ? `<div class="notes">${esc(book.notes)}</div>` : '<p class="empty">No notes.</p>'}

<h3>Share</h3>
<div class="share">
  <input id="share-url" readonly value="${esc(shareUrl)}" onfocus="this.select()">
  <button type="button" onclick="navigator.clipboard.writeText(document.getElementById('share-url').value).then(() => this.textContent = 'Copied!')">Copy link</button>
</div>

<p><a href="/">&larr; All books</a></p>`);
}

export function notFoundPage() {
  return layout('Not found', `<p>That book doesn't exist.</p><p><a href="/">&larr; All books</a></p>`);
}

