import { createServer } from 'node:http';
import { ValidationError } from './store.js';
import { bookPage, homePage, notFoundPage } from './views.js';

const MAX_BODY_BYTES = 64 * 1024;

export function createApp(store) {
  return createServer(async (req, res) => {
    try {
      await route(store, req, res);
    } catch (err) {
      console.error(err);
      if (!res.headersSent) send(res, 500, 'Something went wrong.', 'text/plain; charset=utf-8');
      else res.end();
    }
  });
}

async function route(store, req, res) {
  const { pathname } = new URL(req.url, 'http://localhost');
  const bookMatch = pathname.match(/^\/books\/([a-f0-9]+)$/);
  const finishMatch = pathname.match(/^\/books\/([a-f0-9]+)\/finish$/);

  if (pathname === '/' && req.method === 'GET') {
    return send(res, 200, homePage(store.list()));
  }

  if (pathname === '/books' && req.method === 'POST') {
    const form = await readForm(req, res);
    if (!form) return;
    try {
      const book = await store.add(form);
      return redirect(res, `/books/${book.id}`);
    } catch (err) {
      if (!(err instanceof ValidationError)) throw err;
      return send(res, 400, homePage(store.list(), { error: err.message, values: form }));
    }
  }

  if (bookMatch && req.method === 'GET') {
    const book = store.get(bookMatch[1]);
    if (!book) return send(res, 404, notFoundPage());
    return send(res, 200, bookPage(book, shareUrl(req, book)));
  }

  if (finishMatch && req.method === 'POST') {
    const book = await store.finish(finishMatch[1]);
    if (!book) return send(res, 404, notFoundPage());
    // Go back to wherever the button was clicked (home or book page).
    const from = req.headers.referer && new URL(req.headers.referer, 'http://localhost').pathname;
    return redirect(res, from === `/books/${book.id}` ? from : '/');
  }

  send(res, 404, notFoundPage());
}

function shareUrl(req, book) {
  const base = process.env.PUBLIC_URL?.replace(/\/+$/, '') || `http://${req.headers.host}`;
  return `${base}/books/${book.id}`;
}

function send(res, status, body, type = 'text/html; charset=utf-8') {
  res.writeHead(status, { 'Content-Type': type, 'Content-Length': Buffer.byteLength(body) });
  res.end(body);
}

function redirect(res, location) {
  res.writeHead(303, { Location: location });
  res.end();
}

async function readForm(req, res) {
  let size = 0;
  const chunks = [];
  for await (const chunk of req) {
    size += chunk.length;
    if (size > MAX_BODY_BYTES) {
      send(res, 413, 'Form too large.', 'text/plain; charset=utf-8');
      req.destroy();
      return null;
    }
    chunks.push(chunk);
  }
  return Object.fromEntries(new URLSearchParams(Buffer.concat(chunks).toString('utf8')));
}

