import { mkdtemp, readFile, rm, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { afterEach, beforeEach, describe, expect, it } from 'vitest';
import { createApp } from '../src/app.js';
import { openStore } from '../src/store.js';

let dir, dataFile, server, base;

async function start() {
  const store = await openStore(dataFile);
  server = createApp(store);
  await new Promise((r) => server.listen(0, '127.0.0.1', r));
  base = `http://127.0.0.1:${server.address().port}`;
}

async function stop() {
  await new Promise((r) => server.close(r));
}

function post(path, fields = {}, headers = {}) {
  return fetch(base + path, {
    method: 'POST',
    body: new URLSearchParams(fields),
    redirect: 'manual',
    headers,
  });
}

async function addBook(fields) {
  const res = await post('/books', fields);
  expect(res.status).toBe(303);
  return res.headers.get('location').split('/').pop();
}

beforeEach(async () => {
  dir = await mkdtemp(join(tmpdir(), 'books-'));
  dataFile = join(dir, 'books.json');
  await start();
});

afterEach(async () => {
  await stop();
  await rm(dir, { recursive: true, force: true });
});

describe('books app', () => {
  it('shows empty lists on first open', async () => {
    const html = await (await fetch(base + '/')).text();
    expect(html).toContain('Currently reading');
    expect(html).toContain('Nothing on the go right now.');
    expect(html).toContain('No finished books yet.');
  });

  it('adds a book and shows its detail page', async () => {
    const id = await addBook({ title: 'Dune', author: 'Frank Herbert', notes: 'Spice must flow' });
    const res = await fetch(`${base}/books/${id}`);
    expect(res.status).toBe(200);
    const html = await res.text();
    expect(html).toContain('<h2>Dune</h2>');
    expect(html).toContain('by Frank Herbert');
    expect(html).toContain('Spice must flow');
    expect(html).toContain(`value="${base}/books/${id}"`);

    const home = await (await fetch(base + '/')).text();
    expect(home).toContain(`href="/books/${id}"`);
  });

  it('moves a book to finished', async () => {
    const id = await addBook({ title: 'Emma', author: 'Jane Austen' });
    const res = await post(`/books/${id}/finish`);
    expect(res.status).toBe(303);
    expect(res.headers.get('location')).toBe('/');

    const home = await (await fetch(base + '/')).text();
    const [reading, finished] = home.split('<h2>Finished</h2>');
    expect(reading).not.toContain('Emma');
    expect(finished).toContain('Emma');
  });

  it('returns to the book page when finished from there', async () => {
    const id = await addBook({ title: 'Emma', author: 'Jane Austen' });
    const res = await post(`/books/${id}/finish`, {}, { referer: `${base}/books/${id}` });
    expect(res.headers.get('location')).toBe(`/books/${id}`);
  });

  it('keeps books after a restart', async () => {
    const id = await addBook({ title: 'Middlemarch', author: 'George Eliot' });
    await post(`/books/${id}/finish`);
    await stop();
    await start();

    const html = await (await fetch(`${base}/books/${id}`)).text();
    expect(html).toContain('Middlemarch');
    expect(html).toContain('Finished');
    const saved = JSON.parse(await readFile(dataFile, 'utf8'));
    expect(saved).toHaveLength(1);
  });

  it('rejects a book without a title and keeps what was typed', async () => {
    const res = await post('/books', { title: '  ', author: 'Someone', notes: 'kept' });
    expect(res.status).toBe(400);
    const html = await res.text();
    expect(html).toContain('Please enter a title.');
    expect(html).toContain('value="Someone"');
    expect(html).toContain('>kept</textarea>');
  });

  it('escapes user input', async () => {
    const id = await addBook({ title: '<script>alert(1)</script>', author: 'A "quoted" name' });
    const html = await (await fetch(`${base}/books/${id}`)).text();
    expect(html).not.toContain('<script>alert(1)</script>');
    expect(html).toContain('&lt;script&gt;');
    expect(html).toContain('A &quot;quoted&quot; name');
  });

  it('404s for unknown books', async () => {
    expect((await fetch(`${base}/books/abc123`)).status).toBe(404);
    expect((await post('/books/abc123/finish')).status).toBe(404);
  });

  it('refuses to start over a corrupt data file', async () => {
    await writeFile(dataFile, '{not json');
    await expect(openStore(dataFile)).rejects.toThrow();
  });
});

